import 'dart:convert';
import 'package:http/http.dart' as http;

Future<Map<String, dynamic>> fetchUserProfile(String userId, String token) async {
  final response = await http.get(
    Uri.parse('https://api.yourdomain.com/v1/users/$userId'),
    headers: {
      'Authorization': 'Bearer $token',
      'Content-Type': 'application/json',
    },
  );

  if (response.statusCode == 200) {
    return jsonDecode(response.body);
  } else {
    throw Exception('Failed to load user profile: ${response.statusCode} ${response.body}');
  }
}

